StyleSheet:
/* Liquid Glass: a clear capsule floating above the taskbar. The bar, its menus and notifications show the
   blurred desktop wallpaper behind them, bent at the rim by the theme's shader; "tint" is how much glass colour
   lies over that picture. Without a backdrop the same surfaces are plain translucent glass. */
.bar { height: 50px; padding: 5px; gap: 2px; border-radius: var(--p-roundness); offset: var(--p-float); box-shadow: 0px 8px 22px rgba(0,0,0,0.22);
       background: alpha(var(--bar-bg), var(--p-tint)); backdrop: var(--p-backdrop); backdrop-blur: var(--p-blur); }
.tab { height: 40px; padding: 0px 18px; border-radius: var(--p-roundness); font-size: 13px; font-weight: semibold; indicator: none; stagger: 36ms; }
.tab:hover { background: alpha(#FFFFFF, 0.10); }
.tab:selected { background: alpha(#FFFFFF, 0.20); }
.menu { width: 304px; padding: 10px; gap: 2px; border-radius: 26px; offset: 10px; box-shadow: 0px 14px 34px rgba(0,0,0,0.28);
        background: alpha(var(--menu-bg), var(--p-tint)); backdrop: var(--p-backdrop); backdrop-blur: var(--p-blur); }
.menu-item { height: 44px; padding: 0px 12px; border-radius: 16px; icon-size: 26px; stagger: 22ms; }
.menu-item:hover { background: alpha(#FFFFFF, 0.14); }
.menu-item:selected { background: alpha(#FFFFFF, 0.18); }
.button { min-height: 36px; padding: 6px 18px; border-radius: 18px; font-size: 13px; font-weight: semibold; background: alpha(var(--text), 0.08); }
.button:hover { background: alpha(var(--text), 0.06); }
.button-primary { background: var(--accent); }
.input { min-height: 36px; padding: 6px 14px; border-radius: 18px; background: alpha(var(--text), 0.06); }
.card { padding: 20px 24px; gap: 12px; border-radius: 22px; background: alpha(var(--card-bg), 0.55); }
.window { border-radius: 16px; border-width: 0px; }
.titlebar { height: 44px; }
.sidebar { width: 220px; margin: 2px 6px 14px 14px; padding: 4px 0px; border-radius: 24px; background: alpha(var(--sidebar-bg), 0.5); }
.sidebar-item { height: 40px; padding: 0px 14px; margin: 2px 0px; border-radius: 16px; }
.sidebar-item:hover { background: alpha(var(--text), 0.06); }
.sidebar-item:selected { background: alpha(var(--text), 0.12); }
.toast { border-radius: 22px; border-width: 0px; box-shadow: 0px 12px 28px rgba(0,0,0,0.28);
         background: alpha(var(--popup-bg), var(--p-tint)); backdrop: var(--p-backdrop); backdrop-blur: var(--p-blur); }
